-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT forma_pagamento_sk,count(*) registros,count(DISTINCT order_id) pedidos,sum(payment_value) payment_value FROM g GROUP BY 1) SELECT d.forma_pagamento_sk,d.payment_type,d.membro_tipo,coalesce(a.registros,0) registros,coalesce(a.pedidos,0) pedidos,a.payment_value FROM gold.dim_forma_pagamento d LEFT JOIN a USING(forma_pagamento_sk) ORDER BY d.forma_pagamento_sk;
